"""Read-only visual summary for a corporate closing case."""
from html import escape
import corporate_close_calc as calc

def won(value):return f'{int(value or 0):,}'
def pct(value):return f'{float(value or 0):.2f}%'
def _bar(value,maximum,color='#159466'):
    width=max(0,min(100,(abs(float(value))/maximum*100) if maximum else 0))
    return f'<div class="bar"><i style="width:{width:.2f}%;background:{color}"></i></div>'

def html(company,year,payload,adjustments,income,tax):
    flow=calc.flow(payload.get('values',{}),adjustments);adj=calc.adjustment_totals(adjustments)
    sales=flow['sales'];gross=flow['gross_profit'];operating=flow['operating_profit'];pretax=flow['pre_tax'];net=tax['net_income'];cost_rate=flow['cost_rate'];prior=flow['prior_sales'];max_sales=max(abs(sales),abs(prior),1)
    kpis=[('매출액',sales,'chart'),('매출총이익',gross,'coins'),('영업이익',operating,'trend'),('법인세차감전순이익',pretax,'calc'),('당기순이익',net,'profit')]
    cards=''.join(f'<article class="kpi {kind}"><small>{label}</small><strong>{won(value)}</strong><span>원</span></article>' for label,value,kind in kpis)
    # Fixed-layout SVG keeps the approved chart readable without an external JS dependency.
    stages=[('매출액',sales,'#159466'),('매출원가',-flow['cost'],'#ef7373'),('판매관리비',-flow['sga'],'#f39b61'),('영업외손익',flow['nonop_income']-flow['nonop_expense'],'#55a9d6'),('세전이익',pretax,'#e7c52c')]
    maxv=max([abs(v) for _,v,_ in stages]+[1]);svg=[]
    for i,(label,value,color) in enumerate(stages):
        height=max(10,abs(value)/maxv*142);x=35+i*150;y=177-height
        svg.append(f'<g><rect x="{x}" y="{y:.1f}" width="92" height="{height:.1f}" rx="5" fill="{color}"/><text x="{x+46}" y="{max(16,y-8):.1f}" text-anchor="middle" class="sv">{won(value)}</text><text x="{x+46}" y="200" text-anchor="middle" class="sl">{label}</text></g>')
    tax_steps=[('과세표준',tax['taxable'],'blue'),('산출세액',tax['output_tax'],'red'),('공제·감면',tax['credits'],'blue'),('기납부세액',tax['prepaid_total'],'blue'),('납부·환급',tax['corp_payable']+tax['local_payable'],'yellow')]
    tax_flow='<span class="arrow">→</span>'.join(f'<div class="taxbox {kind}"><small>{label}</small><strong>{won(value)}</strong></div>' for label,value,kind in tax_steps)
    add=adj['add_amount'];deduct=adj['deduct_amount'];adjust_max=max(add,deduct,1)
    current_rate=flow['pre_tax_rate'];prior_rate=0
    return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>
    *{{box-sizing:border-box}}body{{margin:0;padding:14px;background:#f3f7f5;color:#13241c;font:12px "Malgun Gothic","Noto Sans KR",sans-serif}}.head{{display:flex;align-items:end;justify-content:space-between;margin:2px 2px 12px}}h1{{margin:0;color:#075c40;font-size:24px;border-left:6px solid #159466;padding-left:10px}}.meta{{color:#60756a;font-weight:700}}.kpis{{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:10px}}.kpi{{background:#fff;border:1px solid #bdd3c8;border-radius:10px;padding:12px;box-shadow:0 3px 9px #164d3520;position:relative;overflow:hidden}}.kpi:before{{content:"";position:absolute;left:0;top:0;bottom:0;width:5px;background:#159466}}.kpi.profit{{background:#fff9df;border-color:#e9ce60}}.kpi small{{display:block;font-weight:800;color:#365f4d;margin-bottom:8px}}.kpi strong{{font-size:20px;color:#075c40}}.kpi span{{font-size:10px;margin-left:3px;color:#74877e}}.grid{{display:grid;grid-template-columns:1.45fr 1fr;gap:10px;margin-bottom:10px}}.panel{{background:#fff;border:1px solid #bdd3c8;border-radius:10px;box-shadow:0 3px 9px #164d3518;overflow:hidden}}.panel h2{{font-size:14px;margin:0;background:linear-gradient(180deg,#0b8057,#086947);color:#fff;padding:8px 11px}}.inside{{padding:12px}}svg{{width:100%;height:220px}}.sv{{font-size:10px;font-weight:700;fill:#283b32}}.sl{{font-size:11px;font-weight:700;fill:#284637}}.compare{{display:grid;grid-template-columns:1fr 1fr;gap:14px}}.compare h3{{font-size:12px;margin:0 0 8px}}.row{{display:grid;grid-template-columns:60px 1fr 90px;align-items:center;gap:7px;margin:9px 0}}.bar{{height:13px;background:#e8f0ec;border-radius:8px;overflow:hidden}}.bar i{{display:block;height:100%;border-radius:8px}}.num{{text-align:right;font-weight:700}}.donut{{width:116px;height:116px;border-radius:50%;margin:5px auto;background:conic-gradient(#159466 0 {max(0,min(100,cost_rate)):.2f}%,#dfeae4 0);position:relative}}.donut:after{{content:"원가율\\A {cost_rate:.1f}%";white-space:pre;position:absolute;inset:20px;border-radius:50%;background:#fff;display:grid;place-items:center;text-align:center;font-size:14px;font-weight:800;color:#075c40}}.note{{text-align:center;color:#677e72}}.adjust{{display:grid;grid-template-columns:1fr 1fr;gap:12px}}.adjust .row{{grid-template-columns:100px 1fr 110px}}.taxflow{{display:flex;align-items:center;justify-content:space-between;gap:6px;padding:15px}}.taxbox{{flex:1;text-align:center;padding:12px 6px;border-radius:8px;background:#edf6ff;border:1px solid #b8d2e8}}.taxbox.red{{background:#fff0f0;border-color:#f2bcbc}}.taxbox.yellow{{background:#fff4ad;border-color:#e4c94e}}.taxbox small{{display:block;font-weight:800;margin-bottom:6px}}.taxbox strong{{font-size:15px}}.arrow{{font-size:20px;font-weight:900;color:#668177}}@media(max-width:900px){{.kpis{{grid-template-columns:repeat(2,1fr)}}.grid{{grid-template-columns:1fr}}}}@media print{{body{{background:#fff;padding:0}}.panel,.kpi{{box-shadow:none}}}}
    </style></head><body><div class="head"><h1>{year}년도 법인세 결산 대시보드</h1><div class="meta">{escape(company)} · 단위: 원</div></div><section class="kpis">{cards}</section><section class="grid"><article class="panel"><h2>손익 흐름</h2><div class="inside"><svg viewBox="0 0 760 215" role="img">{''.join(svg)}<line x1="18" y1="178" x2="742" y2="178" stroke="#9bb2a6"/></svg></div></article><article class="panel"><h2>전기 대비 주요 지표</h2><div class="inside compare"><div><h3>매출액 비교</h3><div class="row"><span>전기</span>{_bar(prior,max_sales)}<span class="num">{won(prior)}</span></div><div class="row"><span>당기</span>{_bar(sales,max_sales,'#0a6e4c')}<span class="num">{won(sales)}</span></div><h3>세전이익률</h3><div class="row"><span>당기</span>{_bar(current_rate,100,'#e7c52c')}<span class="num">{pct(current_rate)}</span></div></div><div><div class="donut"></div><p class="note">전기 매출 대비 증감률<br><b>{pct(flow['sales_growth'])}</b></p></div></div></article></section><section class="grid"><article class="panel"><h2>세무조정 구성</h2><div class="inside adjust"><div><div class="row"><span>익금산입·손금불산입</span>{_bar(add,adjust_max,'#159466')}<span class="num">{won(add)}</span></div><div class="row"><span>손금산입·익금불산입</span>{_bar(deduct,adjust_max,'#ef7373')}<span class="num">{won(deduct)}</span></div></div><div><div class="row"><span>원가 조정 순액</span>{_bar(adj['add_cost']-adj['deduct_cost'],adjust_max,'#f39b61')}<span class="num">{won(adj['add_cost']-adj['deduct_cost'])}</span></div><div class="row"><span>판관비 조정 순액</span>{_bar(adj['add_sga']-adj['deduct_sga'],adjust_max,'#55a9d6')}<span class="num">{won(adj['add_sga']-adj['deduct_sga'])}</span></div></div></div></article><article class="panel"><h2>소득구분 요약</h2><div class="inside"><div class="row"><span>각사업연도소득</span>{_bar(income['current_income'],max(abs(income['current_income']),1),'#159466')}<span class="num">{won(income['current_income'])}</span></div><div class="row"><span>과세표준</span>{_bar(income['taxable'],max(abs(income['current_income']),1),'#e7c52c')}<span class="num">{won(income['taxable'])}</span></div><div class="row"><span>감면분 영업외수익</span>{_bar(income.get('exempt_income',0),max(abs(income['current_income']),1),'#55a9d6')}<span class="num">{won(income.get('exempt_income',0))}</span></div></div></article></section><article class="panel"><h2>세액 계산 흐름</h2><div class="taxflow">{tax_flow}</div></article></body></html>'''

def comparison_html(year,rows):
    entered=[r for r in rows if r.get('entered')];count=len(entered);maximum=max([abs(r['sales']) for r in entered]+[1])
    total={key:sum(r[key] for r in entered) for key in ['sales','gross','operating','pretax','net','taxable','credits','payable']}
    average={key:(total[key]//count if count else 0) for key in total}
    cards=''.join(f'<article><small>{label}</small><strong>{won(total[key])}</strong><span>합계</span><em>평균 {won(average[key])}</em></article>' for label,key in [('매출액','sales'),('영업이익','operating'),('세전이익','pretax'),('당기순이익','net'),('납부·환급액','payable')])
    bars=''.join(f'<div class="crow"><b>{escape(r["name"])}</b>{_bar(r["sales"],maximum,"#159466")}<span>{won(r["sales"])}</span>{_bar(r["pretax"],maximum,"#e7c52c")}<span>{won(r["pretax"])}</span>{_bar(r["net"],maximum,"#55a9d6")}<span>{won(r["net"])}</span></div>' for r in entered)
    body=''
    for r in rows:
        if not r.get('entered'):body+=f'<tr class="missing"><th>{escape(r["name"])}</th><td colspan="12">미입력</td></tr>';continue
        body+=f'<tr><th>{escape(r["name"])}</th><td>{won(r["sales"])}</td><td>{won(r["gross"])}</td><td>{won(r["operating"])}</td><td>{won(r["pretax"])}</td><td>{won(r["net"])}</td><td>{pct(r["gross_rate"])}</td><td>{pct(r["operating_rate"])}</td><td>{pct(r["pretax_rate"])}</td><td>{pct(r["net_rate"])}</td><td>{pct(r["cost_rate"])}</td><td>{won(r["taxable"])}</td><td>{won(r["payable"])}</td></tr>'
    return f'''<!doctype html><html lang="ko"><head><meta charset="utf-8"><style>
    *{{box-sizing:border-box}}body{{margin:0;padding:14px;background:#f3f7f5;color:#13241c;font:12px "Malgun Gothic","Noto Sans KR",sans-serif}}h1{{margin:0 0 12px;color:#075c40;font-size:24px;border-left:6px solid #159466;padding-left:10px}}.cards{{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin-bottom:10px}}.cards article,.panel{{background:#fff;border:1px solid #bdd3c8;border-radius:10px;box-shadow:0 3px 9px #164d3518}}.cards article{{padding:12px}}.cards small{{display:block;font-weight:800;color:#365f4d}}.cards strong{{display:block;font-size:18px;color:#075c40;margin:7px 0 2px}}.cards span{{color:#6e8278}}.cards em{{display:block;font-style:normal;color:#71847a;margin-top:5px}}.panel{{overflow:hidden;margin-bottom:10px}}h2{{font-size:14px;margin:0;background:linear-gradient(180deg,#0b8057,#086947);color:#fff;padding:8px 11px}}.inside{{padding:12px}}.legend{{display:grid;grid-template-columns:130px 1fr 120px 1fr 120px 1fr 120px;gap:7px;font-weight:800;color:#456557;margin-bottom:7px}}.crow{{display:grid;grid-template-columns:130px 1fr 120px 1fr 120px 1fr 120px;gap:7px;align-items:center;margin:9px 0}}.bar{{height:12px;background:#e7f0eb;border-radius:7px;overflow:hidden}}.bar i{{display:block;height:100%;border-radius:7px}}.crow span{{text-align:right;font-weight:700}}table{{border-collapse:collapse;width:100%;background:#fff}}th,td{{border:1px solid #c5d4cc;padding:6px;text-align:right;white-space:nowrap}}thead th{{background:#e6f1eb;text-align:center}}tbody th{{text-align:left;background:#f3f7f5}}.missing td{{text-align:center;color:#9a6540;background:#fff6e8;font-weight:700}}tfoot th,tfoot td{{background:#fff4ad;font-weight:800}}@media(max-width:1000px){{.cards{{grid-template-columns:repeat(2,1fr)}}.crow,.legend{{grid-template-columns:100px 1fr 100px}}.crow .bar:nth-of-type(n+2),.crow span:nth-of-type(n+2),.legend span:nth-of-type(n+4){{display:none}}}}
    </style></head><body><h1>{year}년도 회사별 법인결산 비교</h1><section class="cards">{cards}</section><section class="panel"><h2>회사별 손익 비교</h2><div class="inside"><div class="legend"><span>회사</span><span>매출액</span><span>금액</span><span>세전이익</span><span>금액</span><span>당기순이익</span><span>금액</span></div>{bars or '<p>입력된 결산자료가 없습니다.</p>'}</div></section><section class="panel"><h2>회사별 상세 비교</h2><div class="inside"><table><thead><tr><th>회사</th><th>매출액</th><th>매출총이익</th><th>영업이익</th><th>세전이익</th><th>당기순이익</th><th>매출총이익률</th><th>영업이익률</th><th>세전이익률</th><th>순이익률</th><th>원가율</th><th>과세표준</th><th>납부·환급액</th></tr></thead><tbody>{body}</tbody><tfoot><tr><th>입력회사 합계</th><td>{won(total['sales'])}</td><td>{won(total['gross'])}</td><td>{won(total['operating'])}</td><td>{won(total['pretax'])}</td><td>{won(total['net'])}</td><td colspan="5">입력 {count}개사 / 전체 {len(rows)}개사</td><td>{won(total['taxable'])}</td><td>{won(total['payable'])}</td></tr></tfoot></table></div></section></body></html>'''
